import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int P = sc.nextInt();

        int[] f = new int[m + 1];
        int[] g = new int[m + 1];
        int[][] C = new int[m + 1][m + 1];

        f[0] = 1;
        for (int i = 0; i <= m; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i - 1][j] + C[i - 1][j - 1]) % P;
            }
        }

        // Helper method for updating values modulo P
        class Helper {
            void update(int[] array, int index, long y) {
                array[index] += y;
                if (array[index] >= P) {
                    array[index] -= P;
                }
            }
        }
        Helper helper = new Helper();

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= i; j++) {
                long val1 = (long) f[j - 1] * f[i - j] % P * (i + 1) % P * C[i - 1][j - 1] % P;
                helper.update(f, i, val1);

                long val2 = ((long) f[j - 1] * g[i - j] + (long) f[i - j] * g[j - 1]) % P * (i + 1) % P * C[i - 1][j - 1] % P;
                helper.update(g, i, val2);

                long val3 = (long) (C[j][2] + C[i - j + 1][2]) * f[j - 1] % P * f[i - j] % P * C[i - 1][j - 1] % P;
                helper.update(g, i, val3);
            }
        }

        int[][] p = new int[n + 1][m + 1];
        int[][] q = new int[n + 1][m + 1];

        p[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= Math.min(i - 1, m); j++) {
                for (int k = 0; k <= j; k++) {
                    long valP = (long) p[i - k - 1][j - k] * f[k] % P * C[j][k] % P;
                    helper.update(p, i, valP);

                    long valQ = ((long) p[i - k - 1][j - k] * g[k] + (long) q[i - k - 1][j - k] * f[k]) % P * C[j][k] % P;
                    helper.update(q, i, valQ);
                }
            }
            if (i <= m) {
                p[i][i] = f[i];
                q[i][i] = g[i];
            }
        }

        System.out.println(q[n][m]);
        sc.close();
    }
}
